import{_ as t}from"./chunks/introducing-invar.CUPq9qh2.js";import{_ as a,o as n,c as i,aa as o}from"./chunks/framework.CuTukyzC.js";import"./chunks/theme.jdWPvDJU.js";const f=JSON.parse('{"title":"Introducing Invar","description":"A full IDE that lives in your terminal — file tree, git, LSP autocomplete, integrated AI agents that can watch your shell — built almost entirely by AI agents under a mechanical referee, on one kilobyte of ivue.","frontmatter":{"title":"Introducing Invar","description":"A full IDE that lives in your terminal — file tree, git, LSP autocomplete, integrated AI agents that can watch your shell — built almost entirely by AI agents under a mechanical referee, on one kilobyte of ivue.","date":"2026-07"},"headers":[],"relativePath":"blog/introducing-invar.md","filePath":"blog/introducing-invar.md","lastUpdated":1786402255000}'),r={name:"blog/introducing-invar.md"};function s(l,e,h,d,c,u){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="introducing-invar" tabindex="-1">Introducing Invar <a class="header-anchor" href="#introducing-invar" aria-label="Permalink to &quot;Introducing Invar&quot;">​</a></h1><p><img src="'+t+'" alt="Introducing Invar"></p><p>Invar is a code editor that lives entirely in your terminal. Not a text editor with syntax colors — an IDE: file tree, buffer tabs, a git panel with staged/unstaged flows and side-by-side diffs, blame, commit history, language intelligence with hover, diagnostics, go-to-definition and caret-anchored autocomplete, an integrated terminal with staged command execution, image preview (yes, in the terminal), audio narration of AI responses if you want it — and AI agents as first-class citizens of the workspace, not a bolted-on chat box.</p><p>It is named after the alloy that does not deform when heated. Both readings are intended: the codebase is governed by written <strong>invariants</strong>, and the editor is engineered to be the <strong>lowest-heat</strong> way to edit code — it never pays for work you did not ask for.</p><h2 id="what-it-feels-like" tabindex="-1">What it feels like <a class="header-anchor" href="#what-it-feels-like" aria-label="Permalink to &quot;What it feels like&quot;">​</a></h2><p>You open it in any terminal, over any SSH connection, in about the time it takes your shell prompt to draw. Everything on screen is reachable two ways, by rule: every keyboard action has a visible mouse path, and the mouse paths are real — click a splitter and drag it, click the layouts button and pick a preset, click the gear, click the ✕. The rule exists because terminal keyboard handling across emulators is the flaky channel, so the mouse is the reliability floor — a philosophy you feel most when something else is broken and Invar isn&#39;t.</p><p>Scrolling glides with momentum physics tuned like an instrument — a lone wheel notch moves precisely, a sustained fling accelerates, a reversal stops and turns, deterministically. Tab switching is instant on files of any size, because every hot path is O(viewport): the editor renders the window you can see and maintains exact aggregate knowledge (like the widest line in the document) through localized bookkeeping instead of full scans. Twenty-six thousand lines of TypeScript, and the idle CPU cost is zero — a frame renders only when something changed.</p><h2 id="the-agent-is-a-citizen-not-a-plugin" tabindex="-1">The agent is a citizen, not a plugin <a class="header-anchor" href="#the-agent-is-a-citizen-not-a-plugin" aria-label="Permalink to &quot;The agent is a citizen, not a plugin&quot;">​</a></h2><p>Invar embeds real coding agents — Claude and Codex today — behind one backend seam. The agent pane is a pane like any other: it splits beside the terminal, reorders, queues your messages while a turn runs, cancels with Escape, and tells you honestly when a backend has gone quiet. The agent can type a command into your terminal — animated, staged, waiting for <em>you</em> to press Enter — and with the terminal observer it can <em>watch your shell</em>: command boundaries and exit codes flow to it as structured, redacted events, and a footer control picks the policy — respond to every command, only to failures, or accumulate context silently so your next question already knows what happened. Everything it sees passes a redactor first; passwords and secrets never reach a model.</p><h2 id="how-it-was-built-is-the-actual-headline" tabindex="-1">How it was built is the actual headline <a class="header-anchor" href="#how-it-was-built-is-the-actual-headline" aria-label="Permalink to &quot;How it was built is the actual headline&quot;">​</a></h2><p><a href="/blog/agents-built-an-editor">AI agents wrote almost all of it</a>. Not as a stunt — as the operating model. On the heaviest day so far, a fleet of builder agents landed some fifty changes to main in twenty-four hours: new features, physics tuning, a codebase-wide structural conversion, regression hunts — with zero regressions shipped. That throughput is not a property of the agents. It is a property of the method:</p><p><strong>Written invariants.</strong> Every module carries a contract file stating what must always hold, what it generates, and what becomes impossible if it is true. Agents read them, extend them, and are judged against them.</p><p><strong>A grammar, enforced by AST.</strong> Every production file has the same shape — one class, uniform member discipline, everything overridable, <a href="/blog/the-constraint-that-unlocks">no initialization-order traps</a>, a colocated test. A ~200-line checker rejects violations at the gate. Uniform shape is what makes a fleet of independent builders converge instead of drift.</p><p><strong>The referee.</strong> Nothing lands without the full gate: type check, grammar check, invariant-contract check, ~1,300 unit tests, and a registry of fifty-plus <em>driven</em> smokes — a real PTY, a terminal emulator as oracle, byte-level assertions on the actual screen. Not &quot;the function returned the right value&quot; — &quot;the pixel-cell at the splitter is hover-lit when the mouse is there.&quot;</p><p>The result is software where the <a href="/blog/the-object-graph-they-took">object graph</a> has been restructured wholesale multiple times in a single week, at the cost of the diff, because the <a href="/blog/the-brick-the-editor-the-referee">architecture cannot tangle</a> and the referee proves each reshape changed nothing it shouldn&#39;t.</p><h2 id="on-one-kilobyte" tabindex="-1">On one kilobyte <a class="header-anchor" href="#on-one-kilobyte" aria-label="Permalink to &quot;On one kilobyte&quot;">​</a></h2><p>All of it stands on <a href="/guide/introduction">ivue</a> — about a kilobyte of reactive engine. Plain TypeScript classes, made live: state is reactive, inheritance works and stays reactive through <code>super</code> chains, every member is an override seam, and the one coarse render effect repaints exactly when a signal it read has changed. There is no framework in Invar in the usual sense — no store, no reducer, no render tree to reconcile. There are objects, telling the truth, and a loop that asks them what changed.</p><p>Invar is the existence proof we built for a set of claims that sound like slogans until you watch them hold under load: that classes plus a referee beat functions plus convention; that total extensibility is affordable when behavior is mechanically proven; that JavaScript&#39;s <a href="/blog/the-weakness-was-the-strength">dynamism is a strength</a> once it has a witness; and that an AI fleet with written contracts can build and maintain real software faster than the industry believes — without the quality collapse the industry predicts.</p><p>The repo is open. Read the invariants files first — they are the truest documentation any of our software has ever had — then watch the gate run. The editor is what it produces.</p><p><strong><a href="https://github.com/infinite-system/invar" target="_blank" rel="noreferrer">github.com/infinite-system/invar</a></strong></p>',20)])])}const y=a(r,[["render",s]]);export{f as __pageData,y as default};
